public class WordSearch{static boolean dfs(char[][]g,String w,int i,int r,int c,boolean[][]v){if(i==w.length())return true;if(r<0||c<0||r==g.length||c==g[0].length||v[r][c]||g[r][c]!=w.charAt(i))return false;v[r][c]=true;boolean f=dfs(g,w,i+1,r+1,c,v)||dfs(g,w,i+1,r-1,c,v)||dfs(g,w,i+1,r,c+1,v)||dfs(g,w,i+1,r,c-1,v);v[r][c]=false;return f;}public static void main(String[]a){char[][]g={{'A','B','C','E'},{'S','F','C','S'},{'A','D','E','E'}};System.out.println(dfs(g,"ABCCED",0,0,0,new boolean[3][4]));}}